import { describe, it } from 'node:test';
import assert from 'node:assert';
import { intCoreTag, NOT_RESOLVED, load } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // signed binary integers, explicitly tagged, must still resolve on CORE schema
    assert.strictEqual(intCoreTag.resolve("-0b101", true, "tag:yaml.org,2002:int"), -5);
    assert.strictEqual(intCoreTag.resolve("+0b11", true, "tag:yaml.org,2002:int"), 3);
    assert.strictEqual(load('!!int "-0b101"'), -5);
    assert.notStrictEqual(intCoreTag.resolve("-0b101", true, "tag:yaml.org,2002:int"), NOT_RESOLVED);
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, CORE_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('explicit !!int octal with unsigned value resolves', () => {
    assert.strictEqual(load('!!int 0o17'), 15);
  });
  it('explicit octal with sign still resolves', () => {
    assert.strictEqual(load('!!int -0o17'), -15);
  });
});

